import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

/// SEVO brand logo recreated with maximum clarity and precision from the
/// authoritative brand artwork.
///
/// - Transparent background with clean anti-aliasing (no white fringe or halo)
/// - Solid, vibrant brand colors: electric blue gradient for S/V/O and top/bottom of E,
///   and vibrant green for the middle bar of E
/// - Ultra-crisp rendering on high-DPI mobile screens
class SevoLogo extends StatelessWidget {
  const SevoLogo({
    super.key,
    this.width,
    this.height,
  });

  final double? width;
  final double? height;

  static const String _logoBase64 =
      '';

  @override
  Widget build(BuildContext context) {
    final Uint8List bytes = base64Decode(_logoBase64);

    return Image.memory(
      bytes,
      width: width,
      height: height,
      fit: BoxFit.contain,
      filterQuality: FilterQuality.high,
      gaplessPlayback: true,
    );
  }
}
